import{H as e,bt as t,gt as n,it as r,nt as i,tt as a}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var o=JSON.parse(`{"title":"Notes","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/notes.md","filePath":"reporting/notes.md","lastUpdated":1787125749000}`),s={name:`reporting/notes.md`};function c(e,o,s,c,l,u){let d=t(`BadgePro`);return n(),a(`div`,null,[o[0]||=i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /reporting/notes.md for this page in Markdown format</div><h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h1><p>Use <strong>notes</strong> as a scratchpad during an engagement: command output, screenshots, checklists, and anything else you do not want in the final PDF. You organize them in a free-form tree.</p><p>The <strong>report</strong> (sections and findings) is the structured deliverable. It follows the project design and is what you publish for the client.</p><p>SysReptor has two note areas:</p><ul><li><strong>Project notes</strong>: accessible by all project members, follows the project life cycle</li><li><strong>Personal notes</strong>: accessible only by you</li></ul><h2 id="organizing-notes" tabindex="-1">Organizing notes <a class="header-anchor" href="#organizing-notes" aria-label="Permalink to “Organizing notes”">​</a></h2><p>Drag notes in the sidebar to reorder them or move them under another note. Any note can have child notes.</p><p><img src="/images/note-taking.png" alt="Note tree in a project" width="1200" height="630"></p><p>Click the checkbox on a note to cycle through unchecked, checked, and emoji. On <strong>project notes</strong>, you can also set an assignee for ownership during the engagement.</p><p>Select one or more notes and use the menu in the sidebar to import, export, export as PDF, copy, or delete in bulk.</p><p>Project notes are included in <a href="/reporting/version-history">Version History</a>. Personal notes are not.</p><h2 id="note-types" tabindex="-1">Note types <a class="header-anchor" href="#note-types" aria-label="Permalink to “Note types”">​</a></h2><p>Pick a type from the <strong>Add</strong> menu when creating a note.</p><p><strong>Text notes</strong> use the same markdown as <a href="/reporting/markdown-features">report fields</a>. Paste images, upload files, and paste command output as you go.</p><p><strong>Excalidraw notes</strong> open an embedded <a href="https://excalidraw.com/" target="_blank" rel="noreferrer">Excalidraw</a> canvas for diagrams and sketches.</p><p><img src="/images/note_excalidraw.gif" alt="Excalidraw notes" width="1167" height="691"></p><h2 id="downloading-files" tabindex="-1">Downloading files <a class="header-anchor" href="#downloading-files" aria-label="Permalink to “Downloading files”">​</a></h2><p>Files attached to a note are downloaded by clicking the file link in the preview.</p><p>Corporate proxies and firewalls often inspect downloads and block the files pentesters work with, such as tool output, captures or proof of concept code. <strong>Right-click a file link</strong> and choose <em>Download via encrypted channel</em> to work around this.</p><p><img src="/images/encrypted-download.png" alt="Download a file via an encrypted channel" width="1500" height="520"></p><p>The file is then transferred as an encrypted text stream and decrypted in your browser. Proxies see neither the file content, nor its content type, nor its filename. The key is generated by your browser for every download, so a recorded response cannot be decrypted afterwards.</p><p>The stream is compressed, so an encrypted download transfers roughly the same number of bytes as a normal one.</p><p>This hides the download from proxies that inspect content. It is not a protection against a proxy that intercepts TLS and specifically targets SysReptor, because the key is sent over the same connection.</p><h2 id="collaborative-editing" tabindex="-1">Collaborative editing <a class="header-anchor" href="#collaborative-editing" aria-label="Permalink to “Collaborative editing”">​</a></h2>`,25),r(d),o[1]||=i(`<p>Several pentesters can edit the same note at once; changes sync in real time. See <a href="/reporting/collaborative-editing">Collaborative Editing</a>.</p><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to “Sharing”">​</a></h2><p>Use the share button on a note to give someone without a SysReptor login access via a public link. The link includes that note and all of its children.</p><p>You can create multiple links per note. Each link has its own settings:</p><ul><li><strong>Password</strong>: Optional. Visitors must enter the password in addition to opening the link.</li><li><strong>Expire date</strong>: The link expires after this date.</li><li><strong>Read-only</strong> or <strong>read-write access</strong>: When write access is enabled, visitors can edit note contents; otherwise the link is read-only.</li><li><strong>Revoked</strong>: Disable the link immediately without deleting it.</li><li><strong>Comment</strong>: Optional, internal comment about the share link to tell links apart and document with whom the link was shared.</li></ul><p>The link exposes the note and its children, plus files and images that were linked in that tree when the share was created, and any files uploaded through that share. Editing notes (by visitors or project members) cannot automatically pull in other existing project or personal files. If someone references a file that is not yet on the share, project members can use <strong>Review shared files</strong> to approve it and make it visible on the link. To expose a file without approval, re-upload it to the shared note tree.</p><p>On <strong>Publish</strong>, <em>Share by Link</em> generates the report PDF, creates a project note with the file attached, and opens the same sharing dialog so you can send the PDF to the client.</p><p><img src="/images/share_notes.gif" alt="Share notes" width="1105" height="712"></p><p>Instance administrators can turn off note sharing with <code>DISABLE_SHARING</code> in <a href="/setup/configuration#application-settings">Application Settings</a> or <code>app.env</code>.</p>`,9)])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};